// ---------------------------------------------------------------------------
// R_alloc — arena-backed raw memory allocator (Category C, core item).
//
// Official signature (R_ext/Memory.h):
//   char *R_alloc(R_SIZE_T nmemb, int size);
//
// The second argument is int in the original declaration even though callers
// always pass sizeof(T).  The fake matches this exactly.  The cast of size to
// std::size_t before multiplication prevents signed-integer overflow.
//
// Every call in rpart reaches this function through the ALLOC macro:
//   #define ALLOC(a,b)  R_alloc(a,b)     [rpart.h:25]
//
// Three structural usage patterns (all share the same fake — listed for
// documentation):
//   P1: Flat primitive array   — e.g., (int *) ALLOC(n, sizeof(int))
//   P2: Pointer-of-pointer vec — e.g., (double **) ALLOC(rp.nvar, sizeof(double *))
//   P3: Struct block           — e.g., (pNode) ALLOC(1, nodesize)
//
// On OOM: arena_alloc() throws std::bad_alloc (std::malloc failure inside the
// arena block). The .Call boundary try/catch must catch std::bad_alloc in
// addition to RError.
// ---------------------------------------------------------------------------
inline char *R_alloc(R_SIZE_T nmemb, int size) {
    std::size_t bytes = nmemb * static_cast<std::size_t>(size);
    return static_cast<char *>(arena_alloc(bytes));
}

// ---------------------------------------------------------------------------
// S_alloc — zero-initialized arena allocation.
//
// Official signature (R_ext/Memory.h):
//   char *S_alloc(long nmemb, int size);
//
// Like R_alloc but guarantees all bytes are zero (equivalent to calloc).
// Not called directly in rpart source, but declared in Memory.h so it must
// be provided here for the header chain to compile cleanly.
// Delegates to arena_calloc for zero-initialization within the arena frame.
// ---------------------------------------------------------------------------
inline char *S_alloc(long nmemb, int size) {
    return static_cast<char *>(
        arena_calloc(static_cast<std::size_t>(nmemb),
                     static_cast<std::size_t>(size)));
}

// ---------------------------------------------------------------------------
// S_realloc — arena-based resize (allocate new block, copy, zero-extend).
//
// Official signature (R_ext/Memory.h):
//   char *S_realloc(char *p, long new_n, long old_n, int size);
//
// R's real implementation allocates a fresh arena block (no in-place resize
// on the vmalloc stack), copies old_n * size bytes from the old block, then
// zero-fills the extension.  The old block is abandoned in the arena (it will
// be freed at frame exit along with everything else).
//
// The fake mirrors this exactly: arena_alloc for the new block, memcpy, memset.
// Not called in rpart source; provided for completeness / compilation safety.
// ---------------------------------------------------------------------------
inline char *S_realloc(char *old_ptr, long new_n, long old_n, int size) {
    std::size_t new_bytes = static_cast<std::size_t>(new_n)
                            * static_cast<std::size_t>(size);
    std::size_t old_bytes = static_cast<std::size_t>(old_n)
                            * static_cast<std::size_t>(size);
    char *new_ptr = static_cast<char *>(arena_alloc(new_bytes));
    if (old_ptr && old_bytes > 0) {
        std::size_t copy_bytes = (old_bytes < new_bytes) ? old_bytes : new_bytes;
        std::memcpy(new_ptr, old_ptr, copy_bytes);
    }
    if (new_bytes > old_bytes)
        std::memset(new_ptr + old_bytes, 0, new_bytes - old_bytes);
    return new_ptr;
}

// ---------------------------------------------------------------------------
// vmaxget / vmaxset — arena high-water-mark save/restore.
//
// Official signatures (R_ext/Memory.h):
//   void *vmaxget(void);
//   void  vmaxset(const void *);
//
// In real R these allow callers to free everything allocated after the saved
// point. In the fake, the ArenaFrame mechanism provides an equivalent
// guarantee at .Call boundaries (Invariant 2), so these are no-ops.
// Returning nullptr from vmaxget is safe: no rpart code calls vmaxset with
// the result, and the arena's frame stack replaces the vmax save/restore
// idiom entirely.
//
// Note: the original R_ext/Memory.h declares these as "not remapped" — they
// have no Rf_* alias, so no compatibility #define is needed.
// ---------------------------------------------------------------------------
inline void *vmaxget(void) { return nullptr; }
inline void  vmaxset(const void * /*saved*/) {}

// ---------------------------------------------------------------------------
// R_gc / R_gc_running — garbage collector interface.
//
// Official signatures (R_ext/Memory.h):
//   void R_gc(void);
//   int  R_gc_running(void);
//
// R_gc() triggers a full GC in the real runtime; the fake has no GC so it is
// a no-op. R_gc_running() returns 0 (GC is never running in the fake).
// Neither is called in rpart source; provided for compilation completeness.
// ---------------------------------------------------------------------------
inline void R_gc(void) {}
inline int  R_gc_running(void) { return 0; }

// ---------------------------------------------------------------------------
// R_allocLD — long double array arena allocator.
//
// Official signature (R_ext/Memory.h):
//   long double *R_allocLD(R_SIZE_T nelem);
//
// Delegates to arena_alloc with proper alignment via sizeof(long double).
// Not called in rpart source; required so the full Memory.h surface compiles.
// ---------------------------------------------------------------------------
inline long double *R_allocLD(R_SIZE_T nelem) {
    return static_cast<long double *>(
        arena_alloc(nelem * sizeof(long double)));
}

// ---------------------------------------------------------------------------
// R_malloc_gc, R_calloc_gc, R_realloc_gc — GC-aware heap allocators (R 4.2+).
//
// Official signatures (R_ext/Memory.h):
//   void *R_malloc_gc(size_t n);
//   void *R_calloc_gc(size_t n, size_t size);
//   void *R_realloc_gc(void *ptr, size_t size);
//
// In the real runtime these allocate from the GC heap and are collected at
// the next GC cycle. The closest analog in the fake is the arena (Invariant 2):
// blocks allocated here are freed when the enclosing ArenaFrame destructs.
//
// R_realloc_gc cannot resize an arena block in place; it allocates a new
// block, copies the old contents, and leaves the old block in the arena
// (acceptable because the function is not called in rpart and the old block
// is freed at frame exit anyway).
//
// Not called in rpart source; provided for header chain compilation.
// ---------------------------------------------------------------------------
inline void *R_malloc_gc(std::size_t n) {
    return arena_alloc(n);
}

inline void *R_calloc_gc(std::size_t n, std::size_t size) {
    return arena_calloc(n, size);
}

inline void *R_realloc_gc(void *ptr, std::size_t size) {
    // Arena blocks cannot be grown in place.  Allocate a fresh block and copy.
    // The old block is abandoned but will be freed at ArenaFrame destruction.
    void *new_ptr = arena_alloc(size);
    if (ptr) std::memcpy(new_ptr, ptr, size);
    return new_ptr;
}

