// ---------------------------------------------------------------------------
// --- ArenaFrame usage (Category C) ---
//
// Every .Call-registered entry-point that (directly or transitively) calls
// R_alloc or the ALLOC macro MUST declare:
//
//   ArenaFrame _frame;
//
// as the very first local variable in its function body.  This pushes a new
// arena frame onto gArenaStack; every arena_alloc() call made within that
// .Call invocation (including those inside sub-functions such as gini_init(),
// anova_init(), partition(), make_cp_list(), graycode()) allocates into this
// frame.  When the .Call wrapper returns — on either the normal path or the
// exception path — _frame's destructor bulk-frees every arena block acquired
// during the invocation, exactly replicating R's vmalloc arena GC behaviour.
//
// The five rpart entry-points that require ArenaFrame are:
//   rpart, xpred, pred_rpart, rpartexp2, init_rpcallback
//
// Sub-functions called from these (gini.c, anova.c, poisson.c, etc.) share
// their caller's frame and do NOT need their own ArenaFrame.
//
// The SEXP objects returned to Python (allocVector/allocMatrix results) are
// heap-allocated (via std::malloc inside SEXP.h), NOT arena-allocated, and
// therefore survive ArenaFrame destruction.  Python reads their contents
// after the wrapper returns, then calls the SEXP destructor / free_sexp().
//
// Example .Call wrapper:
//
//   extern "C" SEXP rpart_entry(
//           SEXP ncat2, SEXP method2, SEXP opt2, SEXP parms2,
//           SEXP xvals2, SEXP xgrp2, SEXP ymat2, SEXP xmat2,
//           SEXP wt2, SEXP ny2, SEXP cost2) {
//       ArenaFrame _frame;   // <-- first statement; frees all ALLOC/R_alloc
//                            //     scratch when this scope exits
//       try {
//           return rpart(ncat2, method2, opt2, parms2, xvals2, xgrp2,
//                        ymat2, xmat2, wt2, ny2, cost2);
//       } catch (const RError &e) {
//           set_python_error(e.what());
//           return R_NilValue;   // _frame destructs here too
//       } catch (const std::bad_alloc &) {
//           set_python_error("R_alloc: out of memory");
//           return R_NilValue;
//       }
//   }   // _frame destructs here on normal return
// ---------------------------------------------------------------------------

#endif // FAKE_R_ALLOC_H
